operations.schema:
input AgentInfoInput {
  id: String
  name: String
  model: String
  description: String
}

input StartSessionInput {
  threadId: String!
  resourceId: String!
  agent: AgentInfoInput!
  startedAt: DateTime!
}

operations.reducer:
state.threadId = action.input.threadId;
state.resourceId = action.input.resourceId;
state.agent = {
  id: action.input.agent.id || null,
  name: action.input.agent.name || null,
  model: action.input.agent.model || null,
  description: action.input.agent.description || null,
  attachment: null,
};
state.status = 'ACTIVE';
state.startedAt = action.input.startedAt;
state.usage = {
  totalPromptTokens: 0,
  totalCompletionTokens: 0,
  totalTokens: 0,
  totalSteps: 0,
  totalMessages: 0,
  totalToolCalls: 0,
};
state.retryRequestedFor = null;
state.retryRequestedAt = null;

operations.schema:
input SetAgentInfoInput {
  id: String
  name: String
  model: String
  description: String
}

operations.reducer:
if (!state.agent) {
  state.agent = { id: null, name: null, model: null, description: null, attachment: null };
}
if (action.input.id) state.agent.id = action.input.id;
if (action.input.name) state.agent.name = action.input.name;
if (action.input.model) state.agent.model = action.input.model;
if (action.input.description) state.agent.description = action.input.description;

operations.schema:
input EndSessionInput {
  status: SessionStatus!
  endedAt: DateTime!
}

operations.reducer:
if (!state.usage) {
  state.usage = { totalPromptTokens: 0, totalCompletionTokens: 0, totalTokens: 0, totalSteps: 0, totalMessages: 0, totalToolCalls: 0 };
}
if (action.input.totalPromptTokens !== undefined && action.input.totalPromptTokens !== null) state.usage.totalPromptTokens = action.input.totalPromptTokens;
if (action.input.totalCompletionTokens !== undefined && action.input.totalCompletionTokens !== null) state.usage.totalCompletionTokens = action.input.totalCompletionTokens;
if (action.input.totalTokens !== undefined && action.input.totalTokens !== null) state.usage.totalTokens = action.input.totalTokens;
if (action.input.totalSteps !== undefined && action.input.totalSteps !== null) state.usage.totalSteps = action.input.totalSteps;
if (action.input.totalMessages !== undefined && action.input.totalMessages !== null) state.usage.totalMessages = action.input.totalMessages;
if (action.input.totalToolCalls !== undefined && action.input.totalToolCalls !== null) state.usage.totalToolCalls = action.input.totalToolCalls;

operations.schema:
input AddSystemMessageInput {
  id: OID!
  text: String!
  createdAt: DateTime!
}

input SetAgentImageInput {
  attachment: String
}

operations.reducer:
if (!state.agent) {
  state.agent = { id: null, name: null, model: null, description: null, attachment: null };
}
state.agent.attachment = action.input.attachment || null;

operations.schema:
input SetAgentDescriptionInput {
  description: String!
}

operations.reducer:
if (!state.agent) {
  state.agent = { id: null, name: null, model: null, description: null, attachment: null };
}
state.agent.description = action.input.description;

state.interruptRequested = false;
state.retryRequestedFor = null;
state.retryRequestedAt = null;
for (const p of action.input.content) {
  if (p.type === 'TEXT' && !p.text) {
    throw new InvalidContentPartError('TEXT part requires text');
  }
}
const parts = action.input.content.map(p => ({
  id: p.id,
  type: p.type,
  text: p.text || null,
  toolCallId: null,
  toolName: null,
  args: null,
  result: null,
  isError: null,
  mediaType: p.mediaType || null,
  url: p.url || null,
  attachment: p.attachment || null,
  filename: p.filename || null,
  error: null,
}));
state.messages.push({
  id: action.input.id,
  role: 'USER',
  content: parts,
  stepIndex: null,
  createdAt: action.input.createdAt,
  usage: null,
  finishedAt: null,
  finishReason: null,
  pickedUpAt: null,
  failure: null,
});
if (state.usage) state.usage.totalMessages += 1;

operations.schema:
input DeleteUserMessageInput {
  messageId: OID!
}

operations.reducer:
const idx = state.messages.findIndex(m => m.id === action.input.messageId);
if (idx === -1) throw new MessageNotFoundError('Message not found: ' + action.input.messageId);
if (state.messages[idx].role !== 'USER') throw new NotUserMessageError('Can only delete USER messages');
state.messages.splice(idx, 1);
if (state.usage) state.usage.totalMessages -= 1;

operations.schema:
input AbortSessionInput {
  endedAt: DateTime!
}

input InterruptAgentInput {
  _: Boolean
}

input RetryTurnInput {
  userMessageId: OID!
  requestedAt: DateTime!
}

operations.reducer:
const msg = state.messages.find((m) => m.id === action.input.userMessageId);
if (!msg) throw new MessageNotFoundError('Message not found: ' + action.input.userMessageId);
if (msg.role !== 'USER') throw new NotUserMessageError('Can only retry the turn of a USER message');
// A retry starts a turn like a new user message, so it clears a stale interrupt.
state.interruptRequested = false;
state.retryRequestedFor = action.input.userMessageId;
state.retryRequestedAt = action.input.requestedAt;

operations.schema:
input ResumeSessionInput {
  resumedAt: DateTime!
}

operations.reducer:
if (state.status !== 'ERROR') throw new SessionNotResumableError('Only ERROR sessions can be resumed (status: ' + state.status + ')');
state.status = 'ACTIVE';
state.endedAt = null;

for (const p of action.input.content) {
  if ((p.type === 'TEXT' || p.type === 'REASONING') && !p.text) {
    throw new InvalidContentPartError(p.type + ' part requires text');
  }
  if (p.type === 'TOOL_CALL') {
    if (!p.toolCallId) throw new InvalidContentPartError('TOOL_CALL part requires toolCallId');
    if (!p.toolName) throw new InvalidContentPartError('TOOL_CALL part requires toolName');
  }
  if (p.type === 'ERROR' && !p.error) {
    throw new InvalidContentPartError('ERROR part requires error field');
  }
}
const parts = action.input.content.map(p => ({
  id: p.id,
  type: p.type,
  text: p.text || null,
  toolCallId: p.toolCallId || null,
  toolName: p.toolName || null,
  args: p.args || null,
  result: null,
  isError: null,
  mediaType: p.mediaType || null,
  url: p.url || null,
  attachment: p.attachment || null,
  filename: p.filename || null,
  error: p.error || null,
}));
state.messages.push({
  id: action.input.id,
  role: 'ASSISTANT',
  content: parts,
  stepIndex: action.input.stepIndex ?? null,
  createdAt: action.input.createdAt,
  usage: null,
  finishedAt: null,
  finishReason: null,
  pickedUpAt: null,
  failure: null,
});
if (state.usage) {
  state.usage.totalMessages += 1;
  const toolCalls = parts.filter(p => p.type === 'TOOL_CALL').length;
  state.usage.totalToolCalls += toolCalls;
}

operations.schema:
input AppendAssistantContentInput {
  messageId: OID!
  part: AssistantContentPartInput!
}

operations.reducer:
const msg = state.messages.find(m => m.id === action.input.messageId);
if (!msg) throw new MessageNotFoundError('Message not found: ' + action.input.messageId);
if (msg.role !== 'ASSISTANT') throw new NotAssistantMessageError('Can only append to ASSISTANT messages');
const p = action.input.part;
if ((p.type === 'TEXT' || p.type === 'REASONING') && !p.text) {
  throw new InvalidContentPartError(p.type + ' part requires text');
}
if (p.type === 'TOOL_CALL') {
  if (!p.toolCallId) throw new InvalidContentPartError('TOOL_CALL part requires toolCallId');
  if (!p.toolName) throw new InvalidContentPartError('TOOL_CALL part requires toolName');
}
if (p.type === 'ERROR' && !p.error) {
  throw new InvalidContentPartError('ERROR part requires error field');
}
msg.content.push({
  id: p.id,
  type: p.type,
  text: p.text || null,
  toolCallId: p.toolCallId || null,
  toolName: p.toolName || null,
  args: p.args || null,
  result: null,
  isError: null,
  mediaType: p.mediaType || null,
  url: p.url || null,
  attachment: p.attachment || null,
  filename: p.filename || null,
  error: p.error || null,
});
if (state.usage && p.type === 'TOOL_CALL') state.usage.totalToolCalls += 1;

const msg = state.messages.find(m => m.id === action.input.messageId);
if (!msg) throw new MessageNotFoundError('Message not found: ' + action.input.messageId);
const part = msg.content.find(p => p.id === action.input.partId);
if (!part) throw new ContentPartNotFoundError('Content part not found: ' + action.input.partId);
if (action.input.text) part.text = action.input.text;
if (action.input.args) part.args = action.input.args;
if (action.input.error) part.error = action.input.error;

operations.schema:
input SetMessageUsageInput {
  messageId: OID!
  promptTokens: Int
  completionTokens: Int
  totalTokens: Int
}

operations.reducer:
const msg = state.messages.find(m => m.id === action.input.messageId);
if (!msg) throw new MessageNotFoundError('Message not found: ' + action.input.messageId);
msg.usage = {
  promptTokens: action.input.promptTokens ?? null,
  completionTokens: action.input.completionTokens ?? null,
  totalTokens: action.input.totalTokens ?? null,
};

operations.schema:
input FinishAssistantMessageInput {
  messageId: OID!
  finishReason: String
  finishedAt: DateTime!
}

operations.reducer:
const msg = state.messages.find(m => m.id === action.input.messageId);
if (!msg) throw new MessageNotFoundError('Message not found: ' + action.input.messageId);
msg.finishedAt = action.input.finishedAt;
msg.finishReason = action.input.finishReason ?? null;

operations.schema:
input MarkMessagePickedUpInput {
  messageId: OID!
  pickedUpAt: DateTime!
}

operations.reducer:
const msg = state.messages.find((m) => m.id === action.input.messageId);
if (!msg) throw new MessageNotFoundError('Message not found: ' + action.input.messageId);
msg.pickedUpAt = action.input.pickedUpAt;

operations.schema:
input ClearRetryRequestInput {
  _: Boolean
}
